\[\begin{align}
(\vec{A}\cdot\vec{B}) \;&=\; (\vec{B}\cdot\vec{A}) = A_xB_x + A_yB_y + A_zB_z = AB\cos\theta, \tag{1}\\
(\vec{A}\times\vec{B}) \;&=\; -(\vec{B}\times\vec{A}) \tag{2}\\
&=\; (A_yB_z - A_zB_y)\hat{x} + (A_zB_x - A_xB_z)\hat{y} + (A_xB_x - A_yB_x)\hat{z}, \tag{3}\\
